Object.assign(UID.or,{"Yes. Events, Moi entries, helpers, receipts, reports and the Moi Book are free to use. Every new event also gets 20 free message credits for receipts and invitations on WhatsApp or SMS.": "ହଁ। କାର୍ଯ୍ୟକ୍ରମ, ମୋଇ ଏଣ୍ଟ୍ରି, ସହାୟକ, ରସିଦ, ରିପୋର୍ଟ ଓ ମୋଇ ବୁକ୍ ସବୁ ମାଗଣା। ପ୍ରତି ନୂଆ କାର୍ଯ୍ୟକ୍ରମ ସହ WhatsApp କିମ୍ବା SMS ରେ ରସିଦ ଓ ନିମନ୍ତ୍ରଣ ପଠାଇବାକୁ 20ଟି ମାଗଣା ମେସେଜ କ୍ରେଡିଟ ମଧ୍ୟ ମିଳେ।", "Unlimited events, Moi entries, helpers, receipts and the Moi Book. Every new event gets 20 free message credits.": "ଅସୀମିତ କାର୍ଯ୍ୟକ୍ରମ, ମୋଇ ଏଣ୍ଟ୍ରି, ସହାୟକ, ରସିଦ ଓ ମୋଇ ବୁକ୍। ପ୍ରତି ନୂଆ କାର୍ଯ୍ୟକ୍ରମରେ 20ଟି ମାଗଣା ମେସେଜ କ୍ରେଡିଟ।", "More from the blog": "ବ୍ଲଗରୁ ଆହୁରି"});
Object.assign(TA,{"Every Moi, accounted for.": "ஒவ்வொரு மொய்க்கும் கணக்கு.", "Log in with your email and password to open your functions, receive Moi at the counter and close the accounts the same night.": "உங்கள் மின்னஞ்சல், கடவுச்சொல் கொண்டு உள்நுழைந்து விழாக்களைத் திறக்கலாம், கவுண்டரில் மொய் பெறலாம், அதே இரவில் கணக்கை முடிக்கலாம்.", "One app for every function": "எல்லா விழாவுக்கும் ஒரே செயலி", "Wedding": "திருமணம்", "Ear piercing": "காது குத்து", "Housewarming": "புதுமனை புகுவிழா", "Birthday": "பிறந்தநாள்", "Valaikappu": "வளைகாப்பு", "Naming ceremony": "பெயர் சூட்டு விழா", "Manivizha": "மணிவிழா", "Temple festival": "கோயில் திருவிழா", "New to Moi Point?": "Moi Point-க்கு புதியவரா?", "Create account": "கணக்கு உருவாக்கு", "Already have an account?": "ஏற்கனவே கணக்கு உள்ளதா?", "Log in": "உள்நுழை", "Welcome back": "மீண்டும் வருக", "Email or username": "மின்னஞ்சல் அல்லது பயனர் பெயர்", "Password": "கடவுச்சொல்", "Remember me": "என்னை நினைவில் வை", "Forgot password?": "கடவுச்சொல் மறந்துவிட்டதா?", "Helpers log in with the email and password their event owner gave them.": "உதவியாளர்கள், விழா உரிமையாளர் கொடுத்த பயனர் பெயர், கடவுச்சொல் கொண்டு உள்நுழையலாம்.", "Demo accounts: tap to fill": "மாதிரி கணக்குகள்: தொட்டால் நிரம்பும்", "← Back to website": "← வெப்சைட்டுக்குத் திரும்பு", "Start free in two minutes.": "இரண்டு நிமிடத்தில் இலவசமாகத் தொடங்குங்கள்.", "New account": "புதிய கணக்கு", "Create your account": "உங்கள் கணக்கை உருவாக்குங்கள்", "Mobile": "கைபேசி", "Verify": "உறுதிசெய்", "Your details": "உங்கள் விவரங்கள்", "We send a 6-digit code once to confirm the number. After that you log in with your email and password.": "எண்ணை உறுதிசெய்ய ஒருமுறை மட்டும் 6 இலக்க குறியீடு அனுப்புவோம். அதன் பிறகு மின்னஞ்சல், கடவுச்சொல் கொண்டு உள்நுழையலாம்.", "Receipts in 11 languages": "11 மொழிகளில் ரசீதுகள்", "Works even without internet": "இணையம் இல்லாமலும் வேலை செய்யும்", "Verify your mobile": "உங்கள் கைபேசியை உறுதிசெய்யுங்கள்", "Verify and continue": "உறுதிசெய்து தொடரவும்", "Change number": "எண்ணை மாற்று", "Resend code": "குறியீட்டை மீண்டும் அனுப்பு", "One-time code": "ஒருமுறை குறியீடு", "All fields marked": "குறியிட்ட எல்லா புலங்களும்", "are needed. Mobile": "நிரப்ப வேண்டும். கைபேசி", "is verified.": "உறுதிசெய்யப்பட்டது.", "You will log in with this email from next time.": "அடுத்த முறையிலிருந்து இந்த மின்னஞ்சல் கொண்டு உள்நுழைவீர்கள்.", "Confirm password": "கடவுச்சொல்லை உறுதிசெய்", "Use 8 or more characters with letters and numbers": "எழுத்துகளும் எண்களும் கலந்து 8 அல்லது அதற்கு மேல் எழுத்துகள் வையுங்கள்", "Strong password": "வலுவான கடவுச்சொல்", "Good password": "நல்ல கடவுச்சொல்", "Too weak: use 8+ characters with letters and numbers": "மிகவும் பலவீனம்: எழுத்தும் எண்ணும் கலந்து 8+ எழுத்துகள் வையுங்கள்", "I agree to the Moi Point terms and privacy policy": "Moi Point விதிமுறைகளையும் தனியுரிமைக் கொள்கையையும் ஏற்கிறேன்", "Create free account": "இலவச கணக்கு உருவாக்கு", "Forgot your password?": "கடவுச்சொல் மறந்துவிட்டதா?", "Type the email you used when you signed up. We send a link to set a new password.": "பதிவு செய்த மின்னஞ்சலை உள்ளிடுங்கள். புதிய கடவுச்சொல் அமைக்க ஒரு லிங்க் அனுப்புவோம்.", "Password help": "கடவுச்சொல் உதவி", "Reset password": "கடவுச்சொல்லை மாற்று", "Your email": "உங்கள் மின்னஞ்சல்", "Continue": "தொடரவும்", "Your password looks like": "உங்கள் கடவுச்சொல் இப்படி இருக்கும்", "Remember it now? Go back and log in.": "இப்போது நினைவு வந்ததா? திரும்பிச் சென்று உள்நுழையுங்கள்.", "Use another email": "வேறு மின்னஞ்சல்", "Back to log in": "உள்நுழைவுக்குத் திரும்பு", "Open the email and tap the link. It works for 30 minutes.": "மின்னஞ்சலைத் திறந்து லிங்கைத் தொடுங்கள். 30 நிமிடம் வேலை செய்யும்.", "Demo: the email link": "மாதிரி: மின்னஞ்சல் லிங்க்", "Open the reset link": "லிங்கைத் திற", "Set a new password.": "புதிய கடவுச்சொல் அமையுங்கள்.", "Choose a password you will remember. Use 8 or more characters with letters and numbers.": "நினைவில் வைக்கக்கூடிய கடவுச்சொல்லைத் தேர்வு செய்யுங்கள். எழுத்தும் எண்ணும் கலந்து 8+ எழுத்துகள்.", "New password": "புதிய கடவுச்சொல்", "Confirm new password": "புதிய கடவுச்சொல்லை உறுதிசெய்", "Save new password": "புதிய கடவுச்சொல்லைச் சேமி", "This link has expired or was already used": "இந்த லிங்க் காலாவதியானது அல்லது ஏற்கனவே பயன்படுத்தப்பட்டது", "Ask for a new link.": "புதிய லிங்க் கேளுங்கள்.", "Get a new link": "புதிய லிங்க் பெறு", "Enter your email or username": "மின்னஞ்சல் அல்லது பயனர் பெயரை உள்ளிடுங்கள்", "Enter your password": "கடவுச்சொல்லை உள்ளிடுங்கள்", "Email/username or password is wrong. Check and try again, or tap Forgot password.": "மின்னஞ்சல்/பயனர் பெயர் அல்லது கடவுச்சொல் தவறு. சரிபார்த்து மீண்டும் முயலுங்கள், அல்லது ‘கடவுச்சொல் மறந்துவிட்டதா?’ தொடுங்கள்.", "Please fill the marked field": "குறியிட்ட புலத்தை நிரப்புங்கள்", "No account uses this email. Check the spelling.": "இந்த மின்னஞ்சலில் கணக்கு இல்லை. எழுத்துப்பிழை சரிபாருங்கள்.", "Enter your email": "மின்னஞ்சலை உள்ளிடுங்கள்", "Enter a valid email": "சரியான மின்னஞ்சலை உள்ளிடுங்கள்", "Enter your name": "பெயரை உள்ளிடுங்கள்", "Type the password again": "கடவுச்சொல்லை மீண்டும் தட்டச்சு செய்யுங்கள்", "The two passwords are not the same": "இரண்டு கடவுச்சொற்களும் ஒன்றாக இல்லை", "Please agree to the terms to continue": "தொடர விதிமுறைகளை ஏற்கவும்", "This email already has an account. Log in or use another email.": "இந்த மின்னஞ்சலில் ஏற்கனவே கணக்கு உள்ளது. உள்நுழையுங்கள் அல்லது வேறு மின்னஞ்சல் பயன்படுத்துங்கள்.", "Enter the 6-digit code": "6 இலக்க குறியீட்டை உள்ளிடுங்கள்", "That code is not right. Check the latest SMS.": "குறியீடு சரியில்லை. கடைசி SMS-ஐப் பாருங்கள்.", "This code expired. Tap Resend code.": "குறியீடு காலாவதியானது. மீண்டும் அனுப்பு தொடுங்கள்.", "This number already has an account. Log in with your email and password.": "இந்த எண்ணில் ஏற்கனவே கணக்கு உள்ளது. மின்னஞ்சல், கடவுச்சொல் கொண்டு உள்நுழையுங்கள்.", "Password saved. Log in with your new password.": "கடவுச்சொல் சேமிக்கப்பட்டது. புதிய கடவுச்சொல்லுடன் உள்நுழையுங்கள்.", "Switch to dark screens": "இருண்ட திரைக்கு மாற்று", "Switch to light screens": "வெளிச்ச திரைக்கு மாற்று", "Dark screens": "இருண்ட திரை", "Light screens": "வெளிச்ச திரை", "Dark screens on": "இருண்ட திரை இயக்கப்பட்டது", "Light screens on": "வெளிச்ச திரை இயக்கப்பட்டது", "Which function? Type it": "எந்த விழா? தட்டச்சு செய்யுங்கள்", "Which relation? Type it": "என்ன உறவு? தட்டச்சு செய்யுங்கள்", "Start typing to pick one others have used.": "தட்டச்சு செய்தால் மற்றவர்கள் பயன்படுத்தியவை காட்டப்படும்.", "It is saved for next time.": "அடுத்த முறைக்கும் சேமிக்கப்படும்.", "Type the function name": "விழாவின் பெயரைத் தட்டச்சு செய்யுங்கள்", "Type the relationship": "உறவைத் தட்டச்சு செய்யுங்கள்", "Moi Book on WhatsApp": "WhatsApp-ல் மொய் புத்தகம்", "Moi Book PDF sent on WhatsApp": "மொய் புத்தக PDF WhatsApp-ல் அனுப்பப்பட்டது", "Send again": "மீண்டும் அனுப்பு", "Open Moi Book": "மொய் புத்தகத்தைத் திற", "Moi Book PDF sent again on WhatsApp": "மொய் புத்தக PDF மீண்டும் WhatsApp-ல் அனுப்பப்பட்டது", "Message credits are over": "மெசேஜ் கிரெடிட் முடிந்துவிட்டது", "Receipts are not going to guests on WhatsApp or SMS. Buy credits to send them again.": "விருந்தினர்களுக்கு WhatsApp, SMS ரசீதுகள் போகவில்லை. மீண்டும் அனுப்ப கிரெடிட் வாங்குங்கள்.", "Receipts are not going to guests on WhatsApp or SMS. Please tell the event organiser to add credits.": "விருந்தினர்களுக்கு WhatsApp, SMS ரசீதுகள் போகவில்லை. விழா நடத்துபவரிடம் கிரெடிட் சேர்க்கச் சொல்லுங்கள்.", "Buy credits now so every guest keeps getting a receipt.": "ஒவ்வொரு விருந்தினருக்கும் ரசீது போக இப்போதே கிரெடிட் வாங்குங்கள்.", "Please tell the event organiser to add credits soon.": "விரைவில் கிரெடிட் சேர்க்க விழா நடத்துபவரிடம் சொல்லுங்கள்.", "Call organiser": "நடத்துபவரை அழை", "Later": "பிறகு", "Not complete yet · pay at the Moi counter": "இன்னும் முடியவில்லை · மொய் கவுண்டரில் பணம் செலுத்துங்கள்", "Not complete yet · show your UPI payment at the counter": "இன்னும் முடியவில்லை · UPI கட்டணத்தைக் கவுண்டரில் காட்டுங்கள்", "Your Moi counts only after you pay the cash at the counter.": "கவுண்டரில் பணம் செலுத்திய பிறகுதான் உங்கள் மொய் கணக்கில் சேரும்.", "The family checks your UPI payment at the counter, then your receipt comes on WhatsApp.": "குடும்பத்தினர் உங்கள் UPI கட்டணத்தைக் கவுண்டரில் சரிபார்த்த பிறகு WhatsApp-ல் ரசீது வரும்."});
TAP.unshift([/^Send reset link to (.+)$/,e=>`${e}-க்கு லிங்க் அனுப்பு`],[/^Reset link sent to (.+)$/,e=>`${e}-க்கு லிங்க் அனுப்பப்பட்டது`],[/^Resend in (\d+)s$/,n=>`${n} வினாடியில் மீண்டும் அனுப்பலாம்`],[/^(\d+) free message credits for every new function$/,n=>`ஒவ்வொரு புதிய விழாவுக்கும் ${n} இலவச மெசேஜ் கிரெடிட்`],[/^Only (\d+) message credits? left$/,n=>`${n} மெசேஜ் கிரெடிட் மட்டுமே உள்ளது`],[/^Verify your mobile once, set your email and password, and add your first function\. Every new function gets (\d+) free message credits\.$/,n=>`ஒருமுறை கைபேசியை உறுதிசெய்து, மின்னஞ்சல், கடவுச்சொல் அமைத்து, முதல் விழாவைச் சேருங்கள். ஒவ்வொரு புதிய விழாவுக்கும் ${n} இலவச மெசேஜ் கிரெடிட்.`],[/^Every purchase keeps all your credits valid for (\d+) days from that purchase\. Each new event gets (\d+) free credits\.$/,(a,b)=>`ஒவ்வொரு முறை வாங்கும்போதும் உங்கள் எல்லா கிரெடிட்டும் அந்த நாளிலிருந்து ${a} நாள் செல்லும். ஒவ்வொரு புதிய விழாவுக்கும் ${b} இலவச கிரெடிட்.`],[/^When the function ends \((.+)\), the full Moi Book PDF is sent to (.+) on WhatsApp by itself\.$/,(t,n)=>`விழா முடிந்ததும் (${t}), முழு மொய் புத்தக PDF ${n}-க்கு WhatsApp-ல் தானாக அனுப்பப்படும்.`],[/^Please fill the (\d+) marked fields$/,n=>`குறியிட்ட ${n} புலங்களை நிரப்புங்கள்`]);
function tr1(k){if(UIL!=='ta'){const d=UID[UIL];return d&&TA_HAS.call(d,k)?d[k]:null}if(TA_HAS.call(TA,k))return TA[k];for(const [re,f] of TAP){const m=k.match(re);if(m){const r=f(...m.slice(1));if(r!=null)return r}}return null}
/* exact → pattern → leading "· "/"— " → per-segment ("Catering · Annapoorna Caterers · UPI"); names and amounts stay as typed */
function trUI(k){let t=tr1(k);if(t!=null)return t;
  const pm=k.match(/^([·—]\s*)(.+)$/);if(pm){const r=trUI(pm[2]);return r==null?null:pm[1]+r}
  for(const sep of [' · ',' + ']){if(k.includes(sep)){let any=false;const out=k.split(sep).map(p=>{const r=p.trim()?tr1(p.trim()):null;if(r!=null){any=true;return r}return p});if(any)return out.join(sep)}}
  return null}
/* receipts, the Moi Book, user-typed text and the picker keep their own language */
const SKIP='[data-noi18n],.bi,.ticket,.bk,.pr-th,.paper,code,.code,.tx,script,style,textarea';
function l10n(root){
  if(UIL==='en'||!root)return;
  if(root.nodeType===1){[root,...root.querySelectorAll('[placeholder],[aria-label],[title]')].forEach(el=>{if(!el.getAttribute||el.closest(SKIP))return;
    ['placeholder','aria-label','title'].forEach(a=>{const v=el.getAttribute(a);if(!v||el.hasAttribute('data-l-'+a))return;const t=trUI(v.trim());if(t!=null){el.setAttribute(a,t);el.setAttribute('data-l-'+a,'')}})})}
  const nodes=[];if(root.nodeType===3)nodes.push(root);else{const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while((n=w.nextNode()))nodes.push(n)}
  nodes.forEach(nd=>{const p=nd.parentElement;if(!p||p.closest(SKIP))return;const raw=nd.nodeValue,k=raw.trim();if(!k||!/[A-Za-z]/.test(k))return;
    const t=trUI(k);if(t==null||t===k)return;const lead=raw.match(/^\s*/)[0],trail=raw.match(/\s*$/)[0];
    if(true){nd.nodeValue=lead+t+trail;return}
    const s=document.createElement('span');s.className='bi';s.innerHTML=`<span>${esc(t)}</span><i>${esc(k)}</i>`;
    const fr=document.createDocumentFragment();if(lead)fr.append(lead);fr.append(s);if(trail)fr.append(trail);p.replaceChild(fr,nd)});
}
const l10nObs=new MutationObserver(ms=>{if(UIL==='en')return;l10nObs.disconnect();ms.forEach(m=>m.addedNodes.forEach(l10n));l10nObs.observe(document.body,{childList:true,subtree:true})});
l10nObs.observe(document.body,{childList:true,subtree:true});
function langChip(){return `<button type="button" class="lang-chip" data-act="uiLang" data-noi18n aria-label="App language">${ic('globe',16)}<span>${UISHORT[UIL]}</span></button>`}
function uiLangModal(){openModal(`<div data-noi18n>${mh('App language · ஆப் மொழி','Changes every screen, button and message right away')}<div class="md-b"><div class="sheet-list">
  ${UILANGS.map(([k,l,s])=>`<button class="${k===UIL?'on':''}" data-act="setUiLang" data-v="${k}"><span class="lang-big">${UISHORT[k]}</span><div>${l}<small>${s}</small></div>${k===UIL?ic('check',18):''}</button>`).join('')}</div>
  <p class="small muted">Receipts, WhatsApp messages, voice and the Moi Book use each event’s own <b>Receipt language</b>, set in Event Settings. Receipts can also be in Hindi, Telugu, Malayalam or Kannada.</p></div></div>`)}
